    let data = '' 

    response.on('data', (chunk) => { 
        data = data + chunk.toString() 
    }) 

    response.on('end', () => { 
        const body = JSON.parse(data) 
        console.log(body) 
    }) 

}) 

request.on('error', (error) => { 
    console.log('An error', error) 
}) 

request.end() 
